function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function fill(template, row) {
  return (template || '')
    .replace(/{{\s*contact\.first_name\s*}}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/{{\s*email\s*}}/gi, row.email || '')
    .replace(/{{(?!\s*company_name\s*}})[^{}]*}}/gi, '');
}

const tmpl = $input.item.json;
const row = $('Select Newly Won Deals').item.json;
let base = '';
try { base = $env.FRONTEND_BASE_URL || ''; } catch (e) { base = ''; }
const unsubUrl = base + '/unsubscribe/' + (row.unsubscribe_token || '');
const htmlBody = fill(tmpl.body, row).replace(/\n/g, '<br>') + `<br><br><span style="font-size:11px;color:#94a3b8">Don't want these emails? <a href="${unsubUrl}">Unsubscribe</a></span>`;
return [{ json: { to: row.email, subject: fill(tmpl.subject, row), htmlBody } }];

// DMs come from user 1 — unless that user is the recipient (Team Chat never counts your own messages as unread); then from the system sender.
const BOT_USER_ID = 9;
const ownerId = $input.item.json.assigned_user;
const NOTIFIER_USER_ID = ownerId === 1 ? BOT_USER_ID : 1;
const dmKey = [NOTIFIER_USER_ID, ownerId].sort((a, b) => a - b).join('-');
return [{ json: { notifierUserId: NOTIFIER_USER_ID, ownerId, dmKey } }];

const row = $('Select Newly Won Deals').item.json;
const name = [row.first_name, row.last_name].filter(Boolean).join(' ') || 'A contact';
return [{ json: { text: '🎉 Deal WON: ' + (row.deal_name || name) + ' - great work!' } }];

