// Company branding + rep signature for outgoing HTML emails. Everything is off until an admin switches on
// "Add company branding and signatures to emails" in Settings > Company Profile (company_profile.email_branding_enabled).
function buildBrandParts(branding, signatureText, companyName) {
  const b = branding || {};
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const on = b.email_branding_enabled === true;
  if (!on) return { on: false, header: '', footer: '', sig: '', sigText: '' };
  const color = /^#[0-9a-fA-F]{6}$/.test(b.brand_color || '') ? b.brand_color : '#2563EB';
  const logo = /^https?:\/\//i.test(b.logo_url || '')
    ? '<img src="' + esc(b.logo_url) + '" alt="' + esc(companyName) + '" style="max-height:56px;max-width:200px;display:block;margin-bottom:6px">' : '';
  const name = companyName ? '<div style="font-size:18px;font-weight:bold;color:' + color + '">' + esc(companyName) + '</div>' : '';
  const header = (logo || name) ? '<div style="padding-bottom:12px;margin-bottom:16px;border-bottom:3px solid ' + color + '">' + logo + name + '</div>' : '';
  const lines = [b.address, b.phone, b.website, b.email].filter(Boolean).map(esc);
  const note = b.email_footer_note ? '<div style="margin-top:6px">' + esc(b.email_footer_note).replace(/\n/g, '<br>') + '</div>' : '';
  const footer = (lines.length || note)
    ? '<div style="margin-top:24px;padding-top:12px;border-top:1px solid #e2e8f0;font-size:12px;color:#64748b">' + (lines.length ? '<div>' + lines.join(' &middot; ') + '</div>' : '') + note + '</div>' : '';
  const sigText = signatureText && String(signatureText).trim() ? String(signatureText).trim() : '';
  const sig = sigText ? '<div style="margin-top:16px">' + esc(sigText).replace(/\n/g, '<br>') + '</div>' : '';
  return { on: true, header, footer, sig, sigText };
}

// Apply Branding — works out this email's company header and footer and adds them to the item as __brandHeader and
// __brandFooter; the Send node then wraps its own HTML with them. Strictly additive and fail-safe: if branding is
// switched off or anything at all goes wrong, the item passes through untouched and the email goes out exactly as before.
const item = $input.item;
try {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  let b = sd.__brandCache && now - sd.__brandCache.t < 60000 ? sd.__brandCache.data : null;
  if (!b) {
    let base = 'http://localhost:5678';
    try { if ($env.N8N_INTERNAL_URL) base = $env.N8N_INTERNAL_URL; } catch (e) { /* env access blocked */ }
    const r = await this.helpers.httpRequest({ url: base.replace(/\/$/, '') + '/webhook/get-email-branding', method: 'GET', json: true, timeout: 5000 });
    b = r && typeof r === 'object' ? r : {};
    sd.__brandCache = { t: now, data: b };
  }
  if (b.email_branding_enabled === true) {
    const parts = buildBrandParts(b, '', b.company_name || '');
    return { json: { ...item.json, __brandHeader: parts.header, __brandFooter: parts.footer }, binary: item.binary };
  }
} catch (e) { /* branding is optional */ }
return item;

